const menu=document.querySelector('.hamburger'),navEl=document.querySelector('.nav');menu?.addEventListener('click',()=>{const opened=navEl.classList.toggle('open');menu.setAttribute('aria-expanded',opened);menu.textContent=opened?'×':'☰'});
const moreNav=document.querySelector('.nav-more');
const themeToggle=document.querySelector('.theme-toggle');
const updateThemeToggle=()=>{
  if(!themeToggle)return;
  const icon=themeToggle.querySelector('.theme-toggle-visual');
  const enabled=document.documentElement.classList.contains('dark-theme');
  themeToggle.setAttribute('aria-pressed',String(enabled));
  themeToggle.setAttribute('aria-label',enabled?'Turn on light mode':'Turn on dark mode');
  if(icon)icon.textContent=enabled?'☀️':'🌙';
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content',enabled?'#111722':'#f47721');
};
updateThemeToggle();
themeToggle?.addEventListener('click',()=>{
  darkMode=!document.documentElement.classList.contains('dark-theme');
  document.documentElement.classList.toggle('dark-theme',darkMode);
  try{localStorage.setItem(themeStorageKey,darkMode?'dark':'light')}catch{}
  updateThemeToggle();
});
const route=location.pathname.replace(/\/index\.html$/,'/').replace(/\/$/,'')||'/';
document.querySelectorAll('.nav>a,.more-menu a').forEach(link=>{const target=new URL(link.href,location.origin).pathname.replace(/\/index\.html$/,'/').replace(/\/$/,'')||'/';if(target===route)link.setAttribute('aria-current','page')});
document.addEventListener('click',event=>{if(moreNav?.open&&!moreNav.contains(event.target))moreNav.open=false});
moreNav?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{moreNav.open=false;navEl.classList.remove('open');menu?.setAttribute('aria-expanded','false')}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&moreNav?.open){moreNav.open=false;moreNav.querySelector('summary')?.focus()}});
if(home&&matchMedia('(pointer:fine)').matches){document.querySelectorAll('.hero-inner .btn,.home-neet-promo').forEach(button=>{button.classList.add('magnetic-nav');button.addEventListener('pointermove',event=>{const box=button.getBoundingClientRect(),x=(event.clientX-box.left-box.width/2)*.16,y=(event.clientY-box.top-box.height/2)*.18;button.classList.remove('is-returning');button.style.transform=`translate3d(${x}px,${y}px,0)`});button.addEventListener('pointerleave',()=>{button.classList.add('is-returning');button.style.transform='';setTimeout(()=>button.classList.remove('is-returning'),650)})})}
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.resource-card').forEach(card=>card.hidden=btn.dataset.filter!=='All'&&card.dataset.category!==btn.dataset.filter)}));
﻿const apiCall=async(action,options={})=>{const response=await fetch(`/api/faculty?action=${encodeURIComponent(action)}`,{credentials:'same-origin',cache:'no-store',...options});const result=await response.json().catch(()=>({ok:false,message:'The service could not be reached.'}));if(!response.ok||!result.ok)throw new Error(result.message||'The request could not be completed.');return result};
const setFacultyStatus=(element,message,isError=false)=>{if(!element)return;element.textContent=message;element.classList.toggle('is-error',isError);element.classList.toggle('is-success',!isError&&Boolean(message))};
let sharedResources=[];
const renderResourceList=()=>{const list=document.querySelector('[data-faculty-resources]');if(!list)return;document.querySelector('[data-resource-count]').textContent=String(sharedResources.length);list.innerHTML=sharedResources.length?sharedResources.map(item=>`<article class="faculty-resource-row"><div class="faculty-resource-row-icon">${typeIcon(item.type)}</div><div class="faculty-resource-row-copy"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.type)}</span></div><a href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer" class="faculty-open-link">Open ?</a><button type="button" class="faculty-edit" data-edit-resource="${escapeHtml(item.id)}">Edit</button><button type="button" class="faculty-delete" data-delete-resource="${escapeHtml(item.id)}">Delete</button></article>`).join(''):'<p class="faculty-empty-list">No resources yet. Add the first Drive link above.</p>'};
const visibleResources=()=>{const query=(document.querySelector('[data-resource-search]')?.value||'').trim().toLowerCase(),type=document.querySelector('[data-resource-filter]')?.value||'';return sharedResources.filter(item=>(!query||item.title.toLowerCase().includes(query))&&(!type||item.type===type))};
const renderPublicResourceViews=()=>{document.querySelectorAll('[data-resource-track]').forEach(track=>{const full=track.classList.contains('resource-full-grid'),items=full?visibleResources():sharedResources;track.innerHTML=items.length?items.map(resourceCard).join(''):(full?'<div class="resource-empty"><span>✧</span><h3>No matching resources.</h3><p>Try another title or type filter.</p></div>':resourcePlaceholders);track.querySelectorAll('[data-thumbnail]').forEach(image=>image.addEventListener('error',()=>{image.hidden=true;image.closest('.resource-card-preview')?.classList.add('thumbnail-failed')},{once:true}));const shell=track.closest('.resource-carousel-shell'),prev=shell?.querySelector('[data-resource-prev]'),next=shell?.querySelector('[data-resource-next]'),dots=shell?.parentElement.querySelector('[data-resource-dots]'),perPage=matchMedia('(max-width: 560px)').matches?1:matchMedia('(max-width: 800px)').matches?2:4,pages=Math.ceil(sharedResources.length/perPage),hasSlides=!full&&sharedResources.length>4;if(prev)prev.hidden=!hasSlides;if(next)next.hidden=!hasSlides;if(dots){dots.hidden=!hasSlides;dots.innerHTML=hasSlides?Array.from({length:pages},(_,index)=>`<button type="button" aria-label="Show resource group ${index+1}" data-resource-page="${index}"></button>`).join(''):''}track.classList.toggle('has-carousel',hasSlides);if(prev)prev.onclick=()=>track.scrollBy({left:-track.clientWidth,behavior:'smooth'});if(next)next.onclick=()=>track.scrollBy({left:track.clientWidth,behavior:'smooth'});dots?.querySelectorAll('[data-resource-page]').forEach(dot=>dot.addEventListener('click',()=>track.scrollTo({left:Number(dot.dataset.resourcePage)*track.clientWidth,behavior:'smooth'})))})};
const loadSharedResources=async()=>{try{const result=await apiCall('resources');sharedResources=Array.isArray(result.resources)?result.resources:[];renderResourceList();renderPublicResourceViews();applyResourceFilters()}catch(error){document.querySelectorAll('[data-resource-track]').forEach(track=>{track.innerHTML=track.classList.contains('resource-full-grid')?'<div class="resource-empty">Resources are temporarily unavailable.</div>':resourcePlaceholders})}};
const applyResourceFilters=()=>{document.querySelectorAll('.resource-full-grid').forEach(track=>{const items=visibleResources();track.innerHTML=items.length?items.map(resourceCard).join(''):'<div class="resource-empty"><span>✧</span><h3>No matching resources.</h3><p>Try another title or type filter.</p></div>';track.querySelectorAll('[data-thumbnail]').forEach(image=>image.addEventListener('error',()=>{image.hidden=true;image.closest('.resource-card-preview')?.classList.add('thumbnail-failed')},{once:true}))})};
const showResourceViewer=id=>{const item=sharedResources.find(resource=>resource.id===id),viewer=document.querySelector('[data-resource-viewer]');if(!item||!viewer)return;viewer.querySelector('[data-viewer-title]').textContent=item.title;viewer.querySelector('[data-viewer-type]').textContent=item.type;viewer.querySelector('[data-viewer-drive]').href=item.url;const frame=viewer.querySelector('[data-viewer-frame]'),folderNote=viewer.querySelector('[data-folder-note]');if(item.previewUrl){frame.hidden=false;frame.src=item.previewUrl;folderNote.hidden=true}else{frame.hidden=true;frame.removeAttribute('src');folderNote.hidden=false}viewer.hidden=false;document.body.classList.add('resource-viewer-open');viewer.querySelector('[data-viewer-close]').focus()};
const initResourceViewer=()=>{const viewer=document.querySelector('[data-resource-viewer]');if(!viewer)return;const close=()=>{viewer.hidden=true;viewer.querySelector('[data-viewer-frame]').removeAttribute('src');document.body.classList.remove('resource-viewer-open')};viewer.querySelector('[data-viewer-close]').addEventListener('click',close);viewer.addEventListener('click',event=>{if(event.target===viewer)close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!viewer.hidden)close()});document.addEventListener('click',event=>{const card=event.target.closest('[data-resource-open]');if(card)showResourceViewer(card.dataset.resourceOpen)})};
let editingResourceId=null;
const initFacultyPortal=()=>{const auth=document.querySelector('[data-faculty-auth]'),dashboard=document.querySelector('[data-faculty-dashboard]');if(!auth||!dashboard)return;const loginForm=document.querySelector('[data-login-form]'),loginStatus=document.querySelector('[data-login-status]'),resourceForm=document.querySelector('[data-resource-form]'),resourceStatus=document.querySelector('[data-resource-status]'),resourceList=document.querySelector('[data-faculty-resources]'),submit=resourceForm.querySelector('[data-resource-submit]'),cancel=resourceForm.querySelector('[data-resource-cancel]');const showDashboard=()=>{auth.hidden=true;dashboard.hidden=false};const showLogin=()=>{dashboard.hidden=true;auth.hidden=false};const setAddMode=()=>{editingResourceId=null;resourceForm.reset();submit.textContent='Add Resource';cancel.hidden=true};const beginEdit=id=>{const item=sharedResources.find(resource=>resource.id===id);if(!item)return;editingResourceId=id;resourceForm.elements.title.value=item.title;resourceForm.elements.url.value=item.url;resourceForm.elements.type.value=item.type;submit.textContent='Update Resource';cancel.hidden=false;resourceForm.scrollIntoView({behavior:'smooth',block:'center'});resourceForm.elements.title.focus({preventScroll:true})};resourceList.addEventListener('click',async event=>{const edit=event.target.closest('[data-edit-resource]'),remove=event.target.closest('[data-delete-resource]');if(edit){beginEdit(edit.dataset.editResource);return}if(remove)await deleteResource(remove,resourceStatus)});cancel.addEventListener('click',()=>{setAddMode();setFacultyStatus(resourceStatus,'')});loginForm.addEventListener('submit',async event=>{event.preventDefault();const button=loginForm.querySelector('button[type=submit]');button.disabled=true;setFacultyStatus(loginStatus,'Checking login\u2026');try{await apiCall('login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(loginForm)))});loginForm.reset();showDashboard();window.dispatchEvent(new Event("mjm:faculty-login"));await loadSharedResources()}catch(error){setFacultyStatus(loginStatus,error.message,true)}finally{button.disabled=false}});apiCall('me').then(result=>{if(result.ok){showDashboard();window.dispatchEvent(new Event("mjm:faculty-login"));loadSharedResources()}}).catch(error=>setFacultyStatus(loginStatus,error.message,true));document.querySelector('[data-logout]').addEventListener('click',async()=>{try{await apiCall('logout',{method:'POST'})}finally{showLogin();setFacultyStatus(loginStatus,'You have been logged out.')}});document.querySelector('[data-test-drive]').addEventListener('click',()=>{const raw=resourceForm.elements.url.value.trim();try{const url=new URL(raw);if(url.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(url.hostname))throw new Error();window.open(url.toString(),'_blank','noopener,noreferrer')}catch{setFacultyStatus(resourceStatus,'Enter a valid HTTPS Google Drive link first.',true)}});resourceForm.addEventListener('submit',async event=>{event.preventDefault();const updating=Boolean(editingResourceId);submit.disabled=true;cancel.disabled=true;setFacultyStatus(resourceStatus,updating?'Updating resource\u2026':'Adding resource\u2026');try{const body=Object.fromEntries(new FormData(resourceForm));const result=updating?await apiCall('update',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({...body,id:editingResourceId})}):await apiCall('add',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});sharedResources=result.resources||[];setAddMode();renderResourceList();renderPublicResourceViews();applyResourceFilters();await loadSharedResources();setFacultyStatus(resourceStatus,updating?'Resource update ho gaya':'Resource added to Free Resources.')}catch(error){setFacultyStatus(resourceStatus,error.message,true)}finally{submit.disabled=false;cancel.disabled=false}})};
const deleteResource=async(button,status)=>{const id=button.dataset.deleteResource,item=sharedResources.find(resource=>resource.id===id);if(!item||!window.confirm('Ye resource delete karna hai? '+item.title))return;button.disabled=true;setFacultyStatus(status,'Deleting resource\u2026');try{await apiCall('delete',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id})});await loadSharedResources();setFacultyStatus(status,'Resource delete ho gaya')}catch(error){setFacultyStatus(status,error.message,true)}finally{button.disabled=false}};
initFacultyPortal();initResourceViewer();loadSharedResources();initStudentReviews();initFacultyStudentReviews();initFeesPage();
document.querySelector('[data-resource-search]')?.addEventListener('input',applyResourceFilters);document.querySelector('[data-resource-filter]')?.addEventListener('change',applyResourceFilters);


